package com.learnagent.memory;import java.util.UUID;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/knowledge-graph")public class KnowledgeGraphController{private final KnowledgeGraphService service;public KnowledgeGraphController(KnowledgeGraphService service){this.service=service;}@GetMapping public MemoryDtos.GraphView graph(@RequestParam UUID courseId){return service.graph(courseId);}}
